# -*- coding: utf-8 -*-
"""English translations, batch 16 (40 figures)."""
EN = {
"哈波拿": dict(lesson="One key word advancing justice",
 summary="The eunuch who pointed out Haman's gallows.",
 witness="Harbona was a eunuch standing before the king. When Haman's evil was exposed, it was he who spoke up: the gallows Haman made for Mordecai, who spoke up to save the king, still stands at his house! And the king ordered Haman hanged on it. One timely word brought justice to pass.",
 follow=["Speaking the word that advances justice at the crucial moment"],
 caution=[],
 applications=["At the crucial moment, dare to speak the word that brings justice to pass","Notice the injustice near you and speak up in time","Let your speech serve justice, not flattery"],
 prayer="Lord, Harbona's one word advanced the accomplishing of justice. Make me dare to speak at the crucial moment, letting my words serve Your justice. Amen."),
"比革他": dict(lesson="A gatekeeper, yet plotting to harm his master",
 summary="A eunuch who plotted to kill the king.",
 witness="Bigthan was a eunuch who guarded the palace gate, whose duty was to protect the king's safety, yet he conspired with Teresh to harm the king. Exposed by Mordecai, he ended up hanged on a tree. When the one entrusted to guard becomes the inner threat, it is the most dangerous betrayal.",
 follow=[],
 caution=["Entrusted to guard, yet plotting harm","Committing betrayal by inside access"],
 applications=["Hold true loyalty in the position entrusted to guard","Don't betray those who trust you out of discontent","Remember a secret scheme will finally be exposed"],
 prayer="Lord, Bigthan was entrusted to guard the gate yet plotted to harm the king, and was finally exposed. Make me faithfully guard in the position entrusted, not betraying those who trust me out of discontent. Amen."),
"提列": dict(lesson="Harboring resentment, plotting against a benefactor",
 summary="A eunuch who conspired with Bigthan to harm the king.",
 witness="Teresh was a gatekeeper eunuch who, with Bigthan out of resentment, plotted to harm King Ahasuerus. The plot was perceived and exposed by Mordecai, and the two were hanged on a tree. Plotting against the one he should serve out of resentment, he was finally exposed and punished.",
 follow=[],
 caution=["Plotting to harm the one he should serve out of resentment","Betraying those who trust you by conspiracy"],
 applications=["Deal with the resentment in your heart, not letting it brew into conspiracy","Hold faithful loyalty to those you should serve","Remember God will expose a secret plot"],
 prayer="Lord, Teresh plotted to harm the king out of resentment, and was finally exposed and punished. Remove the resentment in my heart, make me loyal to those I should serve, not letting conspiracy grow in the dark. Amen."),
"东方博士": dict(lesson="Following the starlight, coming far to worship the King",
 summary="The wise men who came from the East to worship the infant Jesus.",
 witness="The Magi were Gentile wise men who, seeing the star, came from afar, resolved to worship 'Him who has been born King of the Jews.' In Bethlehem they saw the child, fell down and worshipped, offering gold, frankincense, and myrrh, and obeyed the dream's instruction not to return to Herod. Gentiles sincerely seeking by a faint light finally found the true King.",
 follow=["Sincerely seeking by the light God gives, not minding the distance","Falling down to worship and offering treasures on finding the Lord","Obeying God's instruction, not compromising with evil powers"],
 caution=[],
 applications=["Seriously seek the Lord by the light you have","On finding the Lord, offer your best worship and all you have","Obey God's guidance, not compromising with 'Herod'-type powers"],
 prayer="Lord, the Magi came far by the starlight to worship You and offer treasures. Make me too sincerely seek You, and on finding You, fall down to worship, offer my best, and obey Your guidance. Amen."),
"牧羊人": dict(lesson="Lowly shepherds, the first to hear the good news",
 summary="The shepherds in the fields of Bethlehem who saw the Lord's birth.",
 witness="The shepherds were keeping watch over their flock by night in the fields of Bethlehem, yet the angel appeared to these of society's lowest, announcing the good news of great joy: 'today in the city of David a Savior has been born for you.' They hurried to see, and seeing, spread the matter and gave glory to God. The joyful news of the Savior's birth came first to lowly shepherds.",
 follow=["Hurrying to seek the Lord on hearing the good news","Proclaiming and giving glory to God on seeing the Lord"],
 caution=[],
 applications=["Believe the good news of the gospel comes to lowly you too","Respond and go at once when you hear the Lord's call","On seeing the Lord, spread the good news, giving God glory"],
 prayer="Lord, the joyful news of the Savior's birth came first to lowly shepherds. Make me too hurry to find You, and seeing You, spread it abroad, giving glory to You. Amen."),
"希律大帝": dict(lesson="One who fears losing the throne spares not even infants",
 summary="The king of Judea who slaughtered the infants of Bethlehem.",
 witness="Herod the Great was suspicious and cruel; hearing the 'King of the Jews' was born, he ordered all the boys two and under in Bethlehem killed. He used every means to keep the throne, yet could not keep his own end. One who values position above all will do the darkest things for it.",
 follow=[],
 caution=["Valuing position above all, even harming the innocent","Keeping what he had by suspicion and cruelty"],
 applications=["Examine whether you harm others to 'keep what you have'","Lay down the obsession with status and control","Build your life's security on God, not position"],
 prayer="Lord, Herod the Great spared not even infants to keep his throne. Remove from my heart the obsession with status and control, build my security on You, harming no one. Amen."),
"希律安提帕": dict(lesson="Conscience not dead, yet dragged down by face and lust",
 summary="The tetrarch who killed John the Baptist and questioned Jesus.",
 witness="Herod Antipas imprisoned John the Baptist, yet in his heart 'feared him and gladly heard him'—his conscience not wholly dead. But to not lose face at a birthday banquet, he killed John over an oath; later he mocked Jesus on trial. One led by face and lust step by step forsakes the good he knows.",
 follow=[],
 caution=["Sacrificing the right thing his conscience knew for face and lust","Knowing him righteous, yet unwilling to pay the price to protect him"],
 applications=["Don't do what is against conscience for face and appearance","Be careful with your promises and oaths, not held hostage","On hearing truth, do it, not only 'gladly hear'"],
 prayer="Lord, Herod Antipas killed John for face, against his conscience. Make me not sell out the good I know for lust and face, but gladly obey truth once I hear it. Amen."),
"希律腓力": dict(lesson="A man whose wife was taken, drawn into a crime",
 summary="Herodias' former husband.",
 witness="Herod Philip was Herodias' former husband. His brother Herod Antipas took his wife Herodias, and John the Baptist was imprisoned and killed for rebuking this incestuous marriage. Herod Philip himself has little written, yet he was caught up in a crime arising from lust and power.",
 follow=[],
 caution=["(Background) power and lust intertwined, brewing the sin of killing a righteous man"],
 applications=["See the bitter fruit brewed by lust and power intertwined","Guard the boundaries of marriage, not crossing or seizing","Intercede for those harmed by being caught in others' crimes"],
 prayer="Lord, Herod's house brewed great sin through lust and power. Make me guard the boundaries of marriage and morality, unentangled by lust and power, far from all evil arising from selfish desire. Amen."),
"希罗底": dict(lesson="Hating a righteous man, killing by another's hand",
 summary="The woman who instigated John the Baptist's killing.",
 witness="Herodias, because John the Baptist rebuked her incestuous marriage to Herod Antipas, harbored a grudge and wanted to kill him. She used her daughter's dance at the banquet and Herod's rash oath to demand John's head. One pierced by truth yet unwilling to repent will scheme to remove the one who speaks truth.",
 follow=[],
 caution=["Resenting rather than repenting when rebuked by truth","Removing the one who speaks truth by opportunity and another's hand"],
 applications=["When your fault is pointed out, choose repentance, not resentment","Don't take revenge or remove a rival by another's hand","Guard marriage and morality, not glossing over faults"],
 prayer="Lord, Herodias hated John and killed by another's hand. Make me willingly repent when rebuked by truth, not resent or take revenge, responding by repentance rather than removing truth. Amen."),
"希罗底的女儿": dict(lesson="A dance used as a tool",
 summary="The girl who danced for Herod and asked for John the Baptist's head.",
 witness="She danced at Herod's birthday banquet, pleasing the king to swear an oath of promise; instructed by her mother Herodias, she asked for John the Baptist's head. Young, she became a tool of her mother's hatred—one dance cost a prophet's life. To be used to accomplish evil, how lamentable.",
 follow=[],
 caution=["Being used by others (especially close kin) to do evil","Obeying without discernment, becoming a tool that harms people"],
 applications=["Don't be used by others to do harm","Learn discernment between 'obedience' and right and wrong","Don't take part in evil to please people"],
 prayer="Lord, Herodias' daughter was used by her mother and harmed John. Give me discernment, not to be used to do evil, not to take part in injustice to please people. Amen."),
"居里扭": dict(lesson="A census fixed the time and place of the birth",
 summary="The governor of Syria, in office at the registration.",
 witness="When Quirinius was governor of Syria, a registration was carried out. Luke used this census to set the historical coordinates of Jesus' birth, and it was this decree that brought Joseph with Mary back to Bethlehem—fulfilling the prophecy that the Messiah would be born in Bethlehem. Even one administrative census was in God's plan.",
 follow=[],
 caution=[],
 applications=["Trust God can accomplish His plan through administration and circumstances","See God's hand in the arrangements of the 'big environment'","Don't underestimate seemingly ordinary circumstances' role in salvation history"],
 prayer="Lord, Quirinius' census fulfilled the prophecy of Your birth. Make me see Your hand behind circumstances and decrees, firmly trusting all things are in Your plan. Amen."),
"凯撒奥古斯都": dict(lesson="An emperor's decree fulfills God's prophecy",
 summary="The Roman emperor who ordered the census at Jesus' birth.",
 witness="Caesar Augustus was the Roman emperor whose decree of 'registration,' seemingly just imperial administration, brought Joseph and Mary back to Bethlehem—fulfilling the prophecy that the Messiah must be born in Bethlehem. The highest human power was but a pawn accomplishing God's plan.",
 follow=[],
 caution=["Thinking human power supreme, not knowing there is One who reigns above"],
 applications=["See that God can accomplish His will through the world's power and circumstances","Still believe God reigns even before the 'big trends'","Neither overrate nor fear human authority"],
 prayer="Lord, Augustus' decree fulfilled the prophecy of Your birth. Make me see all things and all power under Your governing, resting and trusting in You amid the big trends. Amen."),
"提庇留": dict(lesson="Dynasties change, salvation advances as ever",
 summary="The Roman emperor during John the Baptist's and Jesus' ministry.",
 witness="Tiberius was the Roman emperor during Jesus' ministry; Luke deliberately set the time coordinate of John the Baptist's coming forth to preach by the year of his reign. The empire's scepter changed hands several times, yet God's timetable of salvation advanced to the exact moment—at 'the fullness of time,' the Lord came.",
 follow=[],
 caution=["Fixing your gaze only on the changing of imperial power"],
 applications=["Trust God's timetable of salvation is unaffected by changes of regime","Fix your eyes on God's plan amid changing times","Remember at 'the fullness of time' God will accomplish His work"],
 prayer="Lord, in Tiberius' reign Your salvation advanced as ever. Make me unmoved by the changing times, fixing my eyes on Your exact plan and timing. Amen."),
"西庇太": dict(lesson="Willingly letting go, so children may answer the Lord's call",
 summary="The father of James and John, a fisherman of Galilee.",
 witness="Zebedee was the father of James and John, a fisherman of Galilee. When Jesus called his two sons, they at once left their father and the boat and followed the Lord. Zebedee did not stop them—he willingly let go, letting his sons answer a higher call, while he kept his own trade.",
 follow=["Willingly letting go, supporting children to answer God's call","Faithful in his ordinary trade"],
 caution=["Not hindering children from following the Lord out of sentiment or family business"],
 applications=["Support family answering God's call, not hindering out of sentiment","Be faithful in your own post and trade","Pray for and let go of your children's spiritual future"],
 prayer="Lord, Zebedee willingly let his two sons leave the boat to follow You. Make me too not hinder those I love from answering Your call, faithful in my own duty. Amen."),
"亚勒腓": dict(lesson="An ordinary father who raised an apostle",
 summary="The father of Matthew (Levi) and James the Less.",
 witness="Alphaeus was the father of the apostle Matthew (Levi) and James the Less. He himself has no recorded deeds, yet was the source of two disciples' identity. An unremarkable father gave his sons to the Lord's call—an ordinary home too can be a cradle of apostles.",
 follow=["Quietly being the root of the next generation's called ones"],
 caution=[],
 applications=["Value the responsibility of raising the next generation to answer the Lord's call","Be faithful in inconspicuous places, with possibly far-reaching influence","Pray for your children to follow the Lord in the future"],
 prayer="Lord, Alphaeus raised Matthew and James the Less. Make me faithfully raise the next generation in inconspicuous places, that they may answer Your call in the future. Amen."),
"小雅各（亚勒腓之子）": dict(lesson="A quiet one among the twelve apostles",
 summary="One of the twelve apostles, also called James the Less.",
 witness="James the Less was the son of Alphaeus, one of the twelve apostles, called 'the Less' to distinguish him from James son of Zebedee. The Gospels record almost none of his words and deeds, yet he was among the twelve the Lord personally chose. To be chosen by the Lord and follow faithfully need not be sensational.",
 follow=["Chosen by the Lord, following quietly and faithfully","Not seeking prominence, willingly behind everyone"],
 caution=[],
 applications=["Willingly be a quiet yet faithful follower","Don't despise your service because you are not noticed","Trust that being chosen by the Lord and faithful to the end is glory"],
 prayer="Lord, James the Less was quietly among the twelve apostles. Make me willingly a quiet, faithful follower, not seeking prominence, only to be chosen by You and faithful to the end. Amen."),
"睚鲁的女儿": dict(lesson="In the Lord's eyes, she was only asleep",
 summary="The girl Jesus raised from the dead.",
 witness="She was the twelve-year-old only daughter of the synagogue ruler Jairus, gravely ill and dead. The house was full of weeping, yet Jesus said 'the girl is not dead but asleep,' and took her hand saying 'Little girl, arise.' Her spirit returned, and she got up and walked at once. Before the Lord who holds life, death is but a sleep that can be awakened.",
 follow=[],
 caution=[],
 applications=["Entrust the life and death of those you love to the Lord who holds life","Keep faith even amid the weeping of 'it's too late'","Trust that in the Lord, death is a sleep that can be awakened"],
 prayer="Lord Jesus, with one word You awakened Jairus' daughter. Make me entrust life and death to You, and trust You even in the deepest grief—in You, death is but a sleep. Amen."),
"血漏的妇人": dict(lesson="Only touch the Lord, and be healed",
 summary="Who was healed by touching Jesus' garment.",
 witness="She had a flow of blood twelve years, spent all she had, sought every physician and grew worse, and by the law was 'unclean,' untouchable. She pressed into the crowd, thinking 'if I just touch His garment, I will be healed,' and at one touch the bleeding stopped and she was healed. Jesus turned and called her 'daughter,' saying 'your faith has saved you.' The faith that, in despair, reaches all-in toward the Lord—He surely sees and answers.",
 follow=["Pressing toward the Lord in faith amid despair","Not shrinking back out of shame or uncleanness, just touching the Lord"],
 caution=[],
 applications=["In long-unhealed troubles, still come to the Lord in faith","Don't shrink back feeling unworthy; the Lord will receive you","Trust that even just 'touching' the Lord, faith is seen"],
 prayer="Lord Jesus, the woman with the hemorrhage touched Your garment and was healed. Make me press toward You in faith amid despair, not shrinking back as unworthy, firmly trusting You see and answer. Amen."),
"毕士大池的病人": dict(lesson="Sick thirty-eight years, the Lord sought him out",
 summary="The man sick thirty-eight years whom Jesus healed.",
 witness="He had lain by the pool of Bethesda thirty-eight years, with no one to help him into the pool, waiting having become a habit of despair. Jesus came on His own and asked: do you want to be healed? One word, 'rise, take up your mat and walk,' accomplished the healing that thirty-eight years' waiting could not. The Lord often seeks out the long-sick, those no one cares for.",
 follow=["Responding to the Lord's word, rising and walking at once","Not letting long disappointment become an excuse for not rising"],
 caution=["Not trapped in 'waiting' and complaint, so as to miss healing"],
 applications=["When the Lord says 'rise,' respond by action","Don't let years of hardship grind into a habit of unbelief","Trust the Lord will seek out the long-overlooked"],
 prayer="Lord Jesus, You sought out the man lying thirty-eight years. Come seek out my long-unhealed places too, that I rise and walk at Your word, no longer trapped in disappointment. Amen."),
"生来瞎眼的人": dict(lesson="Healed, then bravely bearing witness",
 summary="The man born blind whom Jesus healed, who bravely witnessed for the Lord.",
 witness="He was blind from birth; Jesus anointed his eyes with saliva and mud and told him to wash in the pool of Siloam, and he came back seeing. The Pharisees questioned and threatened him repeatedly, but he argued ever more clearly: 'He is a prophet'; 'if this man were not from God, He could do nothing.' Finally cast out of the synagogue, Jesus came to find him and led him to worship. The healed one's most powerful witness is to honestly say 'I was blind, now I see.'",
 follow=["Honestly witnessing the Lord's work in himself","Arguing ever more clearly for the Lord under threat and questioning","When rejected, the Lord Himself will seek him out"],
 caution=[],
 applications=["Give plain witness of 'what I was, what I am now'","Don't shrink under pressure; hold to the reality you've experienced","Trust the Lord will come find you when rejected for His sake"],
 prayer="Lord Jesus, the man born blind received sight and bravely witnessed for You. Make me honestly witness Your work in me, not shrinking under threat, firmly trusting You will seek me out. Amen."),
"叙利腓尼基妇人": dict(lesson="Humble and persistent faith, commended by the Lord",
 summary="The Gentile (Canaanite) woman who pleaded for her daughter and was commended for her faith.",
 witness="She was a Syrophoenician (Canaanite) Gentile woman who pleaded with Jesus for her demon-possessed daughter. Facing the words 'it is not right to take the children's bread and throw it to dogs,' she did not lose heart, but humbly replied: 'even the dogs eat the crumbs from the master's table.' Jesus greatly commended: 'Woman, great is your faith!' and healed her daughter.",
 follow=["Pleading with the Lord in humble, persistent faith","Earnestly interceding for children (loved ones)","Not losing heart when refused, but more humble"],
 caution=[],
 applications=["Plead urgently and without giving up for those you love","When seemingly refused, hold on in humble faith","Learn from her: both humbly admitting yourself and grasping the Lord's mercy"],
 prayer="Lord, the Syrophoenician woman was commended for great, humble, persistent faith. Give me such faith, pleading urgently for those I love, holding Your mercy in humility even when refused. Amen."),
"迦百农的百夫长": dict(lesson="A Roman officer, yet the greatest faith",
 summary="The Roman officer of great faith who asked Jesus to heal his servant.",
 witness="The centurion of Capernaum was a Roman officer who pleaded with Jesus for his dying servant. Knowing well the principle of authority that 'a word makes it so,' he said: just say a word and my servant will be healed; I am not worthy to have You come under my roof. Jesus marveled, saying 'such great faith I have not found in Israel.' A Gentile soldier, yet his faith surpassed the chosen people's.",
 follow=["Trusting the Lord's word with humble yet firm faith","Valuing and caring for those under his charge"],
 caution=[],
 applications=["Like him, believe the Lord's 'one word' is enough","Whatever your background, you can have great faith","Pair faith with humility (I am not worthy)"],
 prayer="Lord Jesus, the centurion of Capernaum trusted Your word with humble great faith. Give me such faith: firmly believing one word from You is enough, coming to You in humility. Amen."),
"百夫长的仆人": dict(lesson="The master's faith brought his healing",
 summary="The servant healed by Jesus from a distance.",
 witness="He was the servant 'valued' by the centurion of Capernaum, sick and near death. The master dared not trouble Jesus to enter, asking only that the Lord 'say a word,' and Jesus healed him. He himself said not a word, yet was healed from afar because of his master's faith and love. Sometimes another's intercession becomes the channel of our grace.",
 follow=[],
 caution=[],
 applications=["Intercede with the Lord for those you treasure (subordinates, family)","Believe the Lord's one word can accomplish healing","Treasure those who intercede with the Lord for you"],
 prayer="Lord Jesus, the centurion's servant was healed because of his master's faith. Teach me to intercede urgently for those I treasure, and make me grateful for those who plead with You for me. Amen."),
"十个长大麻风的": dict(lesson="Ten cleansed, one knew to give thanks",
 summary="Cleansed by Jesus, only one Samaritan returned to give thanks.",
 witness="Ten lepers stood at a distance pleading for Jesus' mercy; the Lord told them to go show themselves to the priest, and on the way they were cleansed. Yet only one (and a despised Samaritan at that) returned, loudly giving glory to God and falling down to give thanks. Jesus asked: were not ten cleansed? Where are the nine? Grace is easy to receive, gratitude rare.",
 follow=["After grace, turning back to give glory to God and offer thanks"],
 caution=["Walking off after receiving grace, forgetting to return and thank","Taking God's mercy for granted"],
 applications=["After grace, remember to return before God to give thanks","Don't be one of the nine who 'got it and left'","Often count and offer thanks for God's mercy"],
 prayer="Lord, ten lepers were cleansed, only one returned to give thanks. Make me not be one of the nine, but turn back when shown grace, often giving glory to You and offering thanks. Amen."),
"格拉森被鬼附的人": dict(lesson="Bound by a legion, set free by the Lord",
 summary="The man possessed by a legion of demons, set free by Jesus.",
 witness="He was possessed by a 'legion' of demons, crying out day and night among the tombs and in the wilds, cutting himself with stones, unrestrainable even by chains. Jesus came, drove out the legion, and he sat clothed and in his right mind. The Lord told him to go home and proclaim what the Lord had done for him. The deepest bondage, the Lord can fully break.",
 follow=["After being set free, going back to proclaim the Lord's grace","Witnessing for the Lord in his own hometown"],
 caution=[],
 applications=["Trust the Lord can break the deepest bondage and darkness","After being set free, witness among those who know you","Intercede for those held by every kind of bondage"],
 prayer="Lord Jesus, You freed the man bound by a legion and restored his right mind. Free all who are bound, and make me proclaim what You have done for me. Amen."),
"迦拿婚筵的新郎": dict(lesson="Where the feast lacked, the Lord quietly supplied",
 summary="The bridegroom in the water-to-wine miracle.",
 witness="He was the bridegroom at the wedding in Cana. Midway through the feast the wine ran out—a great social embarrassment at the time. But Jesus turned water into the best wine, and the master of the feast thought the bridegroom had kept the good wine. The Lord, without his knowing, quietly supplied his lack and covered his embarrassment. The Lord's grace often comes so quietly.",
 follow=[],
 caution=[],
 applications=["Trust the Lord will quietly supply your lack and embarrassment","Bring the 'wine run out' of your life to the Lord","Be grateful for the Lord's grace often in hidden places"],
 prayer="Lord Jesus, You supplied the feast's lack without the bridegroom knowing. Supply quietly in my lack and embarrassment too, and make me grateful for Your hidden grace. Amen."),
"管筵席的": dict(lesson="Tasting the good wine, yet not knowing where it came from",
 summary="The master of the feast who tasted the water-turned wine.",
 witness="At the wedding in Cana, the master of the feast tasted the water-turned wine and said in surprise to the bridegroom: everyone serves the good wine first... but you have kept the good wine until now! He tasted the goodness of the miracle, yet did not know how it came—only the servants who drew the water knew. God's works often come first to those who quietly obey and draw the water.",
 follow=["Receiving God's good gift with delighted surprise"],
 caution=["Only enjoying the result, yet not knowing the Lord who gave it"],
 applications=["When enjoying God's blessing, recognize the Lord who blesses","Be willing to be the one who 'draws the water,' knowing the source of the miracle","Give God glory in the 'good wine' of life"],
 prayer="Lord, the master of the feast tasted the good wine but didn't know its source. When I enjoy Your blessing, make me recognize and thank the Lord who blesses, not just enjoy it. Amen."),
"彼拉多的妻子": dict(lesson="A dream, a warning unheeded",
 summary="Who by a dream warned Pilate not to condemn Jesus.",
 witness="Pilate's wife suffered much in a dream because of Jesus, and sent word to her husband: have nothing to do with that righteous man. By conscience and that strange dream, she tried to stop an unjust condemnation, but alas Pilate would not listen. Sometimes God issues a warning by various means; the question is whether one will listen.",
 follow=["Speaking up and stepping in for a righteous man by conscience","Holding reverence for the warning God sends"],
 caution=[],
 applications=["Speak up for the wronged by conscience, even if unheeded","Notice the warnings God sends by various means","Don't stay silent in matters of injustice"],
 prayer="Lord, Pilate's wife spoke up for a righteous man by conscience. Make me too alert to Your warnings, daring to speak for the wronged, not silent before injustice. Amen."),
"巴拉巴": dict(lesson="The one who deserved death set free, the innocent dying in his place",
 summary="The prisoner released in place of Jesus.",
 witness="Barabbas was a prisoner who had committed insurrection and murder, who should have been crucified. Yet Pilate, by the festival custom, released him and handed the innocent Jesus over to be crucified. Barabbas is a vivid picture of the gospel: the punishment I deserved was borne by the innocent Lord, and I was freely set free.",
 follow=[],
 caution=["(Background) the crowd preferred a murderer over Christ"],
 applications=["Meditate: I am that Barabbas who deserved death yet was set free","Have a grateful, repentant heart because the Lord died in my place","Don't, like the crowd, cast aside Christ for self-interest"],
 prayer="Lord Jesus, Barabbas should have died, yet You bore the punishment for him, and for me. Make me ever remember this free release, responding to Your self-giving love with gratitude and repentance. Amen."),
"亚历山大（古利奈人之子）": dict(lesson="The son of the one who carried the cross",
 summary="The son of Simon of Cyrene, named together with Rufus.",
 witness="Alexander was the son of Simon of Cyrene, named together with his brother Rufus specially in Mark's Gospel. The father, Simon, was forced to carry Jesus' cross, and this family evidently later became known among the believing community. One 'forced' encounter brought the whole family into the faith.",
 follow=["Inheriting the father's spiritual connection with the cross"],
 caution=[],
 applications=["Treasure the family's spiritual memory of meeting Christ","Let the previous generation's faith experience be your root","Trust one 'chance' encounter may change a whole family"],
 prayer="Lord, Simon of Cyrene carried the cross, and his son too is remembered. Make me treasure the family's memory of meeting You, letting the previous generation's experience be my root. Amen."),
"埃提阿伯太监": dict(lesson="God will surely prepare for the one who sincerely seeks",
 summary="The Ethiopian treasurer to whom Philip preached the gospel and baptized.",
 witness="The Ethiopian eunuch was a high-ranking treasurer who came a long way to Jerusalem to worship, and on the way back was still reading Isaiah in his chariot. God specially sent Philip to explain it to him, and on understanding he was baptized at once and went on his way rejoicing. For the one who truly seeks, God will surely prepare an occasion to meet Him.",
 follow=["Sincerely and continually seeking God, not giving up though not understanding","Responding at once and being baptized on understanding the truth"],
 caution=["Not neglecting the seeking of God because of status and busyness"],
 applications=["Keep reading Scripture and seeking, even if you don't understand for now","After understanding the truth, respond at once by action","Trust God will prepare a guide for the one who truly seeks"],
 prayer="Lord, You sent Philip to the sincerely seeking Ethiopian eunuch. Make me keep seeking You, obeying at once on understanding, and make me a guide on another's road. Amen."),
"马利亚（马可的母亲）": dict(lesson="Opening the home, becoming a haven of prayer",
 summary="The hostess of a house church in Jerusalem.",
 witness="Mary was the mother of Mark, who opened her home as a gathering place of prayer for the Jerusalem church. The night Peter came out of prison, the people were earnestly praying in her home. With an 'open home,' she quietly held up the prayer and fellowship of the early church.",
 follow=["Opening her home to receive and supply the church's gatherings","Holding up the community by hospitality and prayer"],
 caution=["Not closing the door of hospitality out of fear of trouble or risk"],
 applications=["Open your home and space to fellowship and prayer","Serve brothers and sisters by reception and hospitality","Be the steady haven of prayer in the community"],
 prayer="Lord, Mary opened her home as a haven of the church's prayer. Make me too willingly open all I have to receive the saints, becoming one who holds up the community's prayer and fellowship. Amen."),
"罗大": dict(lesson="So overjoyed she forgot to open the door",
 summary="The maid who brought the news when Peter came out of prison.",
 witness="Rhoda was a maid in the home of Mark's mother. When Peter was freed from prison by an angel and came knocking, Rhoda recognized his voice and, too overjoyed to open the door, ran in to report, and the people would not believe her. A little maid became the first witness of God's wondrous deliverance—God often gives the surprise first to the most unremarkable.",
 follow=["Holding a simple joy and certainty about God's work","Holding to the reality she heard even when people would not believe"],
 caution=[],
 applications=["Rejoice over God's work with a simple heart","When others don't believe, still hold to what you've experienced","Trust God delights to give the surprise first to the most unremarkable"],
 prayer="Lord, the little maid Rhoda was the first to recognize the rescued Peter. Make me rejoice over Your work with a simple heart, holding to the reality I've experienced even when not believed. Amen."),
"亚迦布": dict(lesson="Receiving prophecy, also willingly suffering",
 summary="The prophet who foretold a famine and Paul's binding.",
 witness="Agabus was a prophet in the early church who foretold a great famine over the world, leading the church to prepare relief early; and at Caesarea, with Paul's belt, bound his own hands and feet, foretelling Paul would be bound in Jerusalem. He faithfully conveyed God's prompting, helping the church prepare ahead.",
 follow=["Faithfully conveying God's reminder, helping the community prepare","Conveying the message by action (not only words)"],
 caution=["When proclaiming coming hardship, neither exaggerate nor conceal"],
 applications=["Prepare ahead for coming difficulties","Be the one who conveys God's reminder in the community","Facing foreknown hardship, still go forward with an entrusting heart"],
 prayer="Lord, Agabus faithfully proclaimed prophecy, helping the church prepare. Make me faithfully convey the reminders I receive, helping those around me prepare ahead and face the future with peace. Amen."),
"犹大（巴撒巴）": dict(lesson="Sent to convey, strengthening everyone",
 summary="A leader sent by the Jerusalem church to Antioch.",
 witness="Judas (Barsabbas) was a leader in the Jerusalem church, sent with Silas to Antioch to convey the decision of the Jerusalem council. They were also prophets, who 'encouraged the brothers with many words and strengthened them.' To be sent to convey is not only to deliver a document, but to strengthen hearts with words.",
 follow=["Faithfully conveying the message entrusted","Strengthening the brothers with words of encouragement"],
 caution=[],
 applications=["Faithfully convey the message entrusted, not smuggling in your own bias","Beyond conveying, encourage and strengthen people with words","Be a reliable bridge in the church's decisions and communication"],
 prayer="Lord, Judas faithfully conveyed the decision and strengthened everyone. Make me faithfully convey the message entrusted, and strengthen the brothers and sisters around me with words of encouragement. Amen."),
"西面（尼结）": dict(lesson="A diverse team leading the church of one heart",
 summary="A prophet and teacher of the church in Antioch.",
 witness="Simeon (called Niger, meaning 'black,' perhaps of African background) was one of the prophets and teachers of the church in Antioch, listed with Lucius of Cyrene, Manaen (brought up with Herod), Barnabas, and Saul. This was a cross-regional, cross-background diverse team who served together, fasted and prayed, and sent out Paul and Barnabas.",
 follow=["Serving of one heart in a diverse team","Seeking the direction of sending through fasting and prayer"],
 caution=[],
 applications=["Work together of one heart in a cross-background team","Value the blessing of diverse co-workers for missions","Seek God's sending through prayer and fasting"],
 prayer="Lord, Simeon served of one heart with co-workers of different backgrounds in Antioch and sent out missionaries. Make me work of one heart in a diverse team, seeking Your sending through prayer. Amen."),
"马念": dict(lesson="Raised in the palace, yet choosing to follow the Lord",
 summary="A leader of the church in Antioch brought up with Herod Antipas.",
 witness="Manaen was 'brought up with' the tetrarch Herod Antipas, yet now was one of the prophets and teachers of the church in Antioch. When his childhood playmate Herod killed John the Baptist and mocked Jesus, Manaen walked an entirely different road—committed to Christ, serving the church. The same origin can lead to entirely different choices.",
 follow=["Not letting origin or connections decide his spiritual direction","Committed to Christ, separated from the old worldly circle"],
 caution=[],
 applications=["Don't let origin or your old circle decide your spiritual choice","Even if those around drift from God, you can still choose to follow","Turn past resources (connections, background) toward serving the Lord"],
 prayer="Lord, Manaen was raised with Herod, yet chose to follow You and serve the church. Make me unbound by origin and the old circle, resolved to commit to You, walking a road separate from the world. Amen."),
"以吕马": dict(lesson="Opposing the true word, sinking into darkness himself",
 summary="Also called Bar-Jesus, the magician struck blind for opposing Paul.",
 witness="Elymas (also Bar-Jesus) was a sorcerer and false prophet who strongly opposed Paul, trying to keep the proconsul from believing the true word. Paul, filled with the Spirit, fixed his eyes and rebuked him for 'deceit and villainy,' striking him temporarily blind. Whoever opposes the true word and hinders people from believing pushes himself into darkness.",
 follow=[],
 caution=["Opposing the true word with deceit and sorcery","Hindering others from seeking and believing God"],
 applications=["Never hinder others from seeking truth and turning to God","Stay far from all deceit and sorcery","Examine whether you are hindering people from drawing near to God"],
 prayer="Lord, Elymas opposed the true word and hindered people from believing, sinking into darkness himself. Make me never hinder people from turning to You, far from deceit, one who draws people near to You. Amen."),
"腓立比的狱卒": dict(lesson="Overnight, from jailer to believer",
 summary="The jailer who believed because of the earthquake and was baptized with his whole household.",
 witness="He was the jailer of Philippi, who at midnight when a great earthquake shook all the doors open, thinking the prisoners had escaped, was about to kill himself. Paul loudly stopped him. Trembling, he fell down and asked 'what must I do to be saved,' and that night his whole household believed and was baptized, and he washed Paul and Silas' wounds and set food before them. God's salvation can turn a person's whole family around overnight.",
 follow=["Sincerely seeking the way of salvation, responding at once","After believing, receiving and serving God's servants with love","Bringing his whole household to the Lord together"],
 caution=[],
 applications=["Seriously ask 'what must I do to be saved'","Once you believe, be baptized and respond by action at once","Hope for and lead your whole household to the Lord together"],
 prayer="Lord, the jailer of Philippi turned his whole household to You overnight. Make me sincerely seek salvation, respond at once, and lead my family to trust and serve You together. Amen."),
"被鬼附的使女": dict(lesson="Being set free surpasses being used",
 summary="The slave girl from whom Paul cast out a spirit of divination.",
 witness="She was a slave girl in Philippi possessed by a spirit of divination, by which her masters gained much profit from fortune-telling. She followed Paul crying out for many days, and Paul cast out the spirit in the name of Jesus. She was set free, but her masters, their hope of gain cut off, angrily accused Paul. In the Lord's eyes, a person's being set free is far more precious than being used to earn money.",
 follow=[],
 caution=["(Background) being treated as a tool for profit"],
 applications=["Value a person's being set free above their 'utility'","Intercede and fight for the freedom of the bound and exploited","Resist the dark powers that bind people in the name of the Lord"],
 prayer="Lord, You freed the slave girl used for profit. Make me value a person's freedom above their usefulness, fight for the freedom of the bound, and resist darkness in Your name. Amen."),
}
